import Foundation
import Testing
@testable import Fuse

/// Replays `Fixtures/fusejs-parity.json`, which is generated by running the real Fuse.js
/// (see `Tests/FuseTests/Fixtures/README.md`) over the same collections, options and queries.
/// Every result — order, `refIndex`, score and match indices — must agree.
@Suite("Fuse.js parity")
struct FuseJSParityTests {
    struct Fixture: Decodable {
        var fuseVersion: String
        var cases: [Case]
    }

    struct Case: Decodable {
        var name: String
        var options: Options
        var keys: [Key]?
        var collection: [Doc]
        var query: Query
        var limit: Int?
        var expected: [Expected]
    }

    struct Options: Decodable {
        var isCaseSensitive: Bool?
        var ignoreDiacritics: Bool?
        var includeMatches: Bool?
        var minMatchCharLength: Int?
        var shouldSort: Bool?
        var findAllMatches: Bool?
        var location: Int?
        var threshold: Double?
        var distance: Int?
        var ignoreLocation: Bool?
        var ignoreFieldNorm: Bool?
        var fieldNormWeight: Double?
        var useExtendedSearch: Bool?
        var useTokenSearch: Bool?
        var tokenMatch: String?

        var fuseOptions: FuseOptions {
            var options = FuseOptions()
            if let v = isCaseSensitive { options.isCaseSensitive = v }
            if let v = ignoreDiacritics { options.ignoreDiacritics = v }
            if let v = includeMatches { options.includeMatches = v }
            if let v = minMatchCharLength { options.minMatchCharLength = v }
            if let v = shouldSort { options.shouldSort = v }
            if let v = findAllMatches { options.findAllMatches = v }
            if let v = location { options.location = v }
            if let v = threshold { options.threshold = v }
            if let v = distance { options.distance = v }
            if let v = ignoreLocation { options.ignoreLocation = v }
            if let v = ignoreFieldNorm { options.ignoreFieldNorm = v }
            if let v = fieldNormWeight { options.fieldNormWeight = v }
            if let v = useExtendedSearch { options.useExtendedSearch = v }
            if let v = useTokenSearch { options.useTokenSearch = v }
            if tokenMatch == "all" { options.tokenMatch = .all }
            return options
        }
    }

    struct Key: Decodable {
        var name: String
        var weight: Double?
    }

    enum Field: Sendable, Decodable {
        case string(String)
        case strings([String])

        init(from decoder: any Decoder) throws {
            let container = try decoder.singleValueContainer()
            if let string = try? container.decode(String.self) {
                self = .string(string)
            } else {
                self = .strings(try container.decode([String].self))
            }
        }
    }

    /// Either a plain string (string collections) or an object with string / string-array fields.
    struct Doc: Sendable, Decodable {
        var text: String?
        var fields: [String: Field] = [:]

        private struct AnyKey: CodingKey {
            var stringValue: String
            var intValue: Int? { nil }
            init?(stringValue: String) { self.stringValue = stringValue }
            init?(intValue: Int) { nil }
        }

        init(from decoder: any Decoder) throws {
            if let container = try? decoder.singleValueContainer(), let string = try? container.decode(String.self) {
                text = string
                return
            }
            let container = try decoder.container(keyedBy: AnyKey.self)
            for key in container.allKeys {
                fields[key.stringValue] = try container.decode(Field.self, forKey: key)
            }
        }

        func key(named name: String) -> FuseKey<Doc>.Value {
            switch fields[name] {
            case .string(let string): return .string(string)
            case .strings(let strings): return .strings(strings)
            case nil: return .none
            }
        }
    }

    indirect enum Query: Decodable {
        case pattern(String)
        case key(String, String)
        case and([Query])
        case or([Query])

        init(from decoder: any Decoder) throws {
            if let container = try? decoder.singleValueContainer(), let string = try? container.decode(String.self) {
                self = .pattern(string)
                return
            }
            enum Keys: CodingKey { case and, or, key, pattern }
            let container = try decoder.container(keyedBy: Keys.self)
            if let and = try container.decodeIfPresent([Query].self, forKey: .and) {
                self = .and(and)
            } else if let or = try container.decodeIfPresent([Query].self, forKey: .or) {
                self = .or(or)
            } else {
                self = .key(try container.decode(String.self, forKey: .key), try container.decode(String.self, forKey: .pattern))
            }
        }

        var fuseQuery: FuseQuery {
            switch self {
            case .pattern(let p): return .pattern(p)
            case .key(let k, let p): return .key(k, pattern: p)
            case .and(let q): return .and(q.map(\.fuseQuery))
            case .or(let q): return .or(q.map(\.fuseQuery))
            }
        }

        var isPlainPattern: Bool {
            if case .pattern = self { return true }
            return false
        }
    }

    struct Expected: Decodable {
        var refIndex: Int
        var score: Double?
        var matches: [ExpectedMatch]
    }

    struct ExpectedMatch: Decodable {
        var key: String?
        var refIndex: Int?
        var value: String
        /// Fuse.js reports inclusive `[start, end]` pairs.
        var indices: [[Int]]
    }

    static let fixture: Fixture = {
        let url = Bundle.module.url(forResource: "fusejs-parity", withExtension: "json", subdirectory: "Fixtures")!
        return try! JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }()

    static var caseNames: [String] { fixture.cases.map(\.name) }

    @Test("fixture is from Fuse.js 7.x")
    func fixtureVersion() {
        #expect(Self.fixture.fuseVersion.hasPrefix("7."))
        #expect(Self.fixture.cases.count > 150)
    }

    @Test("case", arguments: caseNames)
    func parity(caseName: String) throws {
        let testCase = Self.fixture.cases.first { $0.name == caseName }!
        let options = testCase.options.fuseOptions

        let results: [ResultSnapshot]
        if let keyDefinitions = testCase.keys {
            let keys = keyDefinitions.map { definition in
                FuseKey<Doc>(definition.name, weight: definition.weight ?? 1) { $0.key(named: definition.name) }
            }
            let fuse = Fuse(testCase.collection, keys: keys, options: options)
            results = snapshots(run(fuse, query: testCase.query, limit: testCase.limit))
        } else {
            let fuse = Fuse(testCase.collection.map { $0.text! }, options: options)
            results = snapshots(run(fuse, query: testCase.query, limit: testCase.limit))
        }

        try #require(results.count == testCase.expected.count, "result count: got \(results.map(\.refIndex)), expected \(testCase.expected.map(\.refIndex))")
        for (actual, expected) in zip(results, testCase.expected) {
            #expect(actual.refIndex == expected.refIndex, "order: got \(results.map(\.refIndex)), expected \(testCase.expected.map(\.refIndex))")
            if let score = expected.score {
                #expect(approximatelyEqual(actual.score, score), "score for item \(expected.refIndex): \(actual.score) vs \(score)")
            }
            let expectedMatches = expected.matches.map { match in
                FuseMatch(key: match.key, value: match.value, refIndex: match.refIndex, indices: match.indices.map { $0[0] ..< $0[1] + 1 })
            }
            #expect(actual.matches == expectedMatches, "matches for item \(expected.refIndex)")
        }
    }

    private func run<Item>(_ fuse: Fuse<Item>, query: Query, limit: Int?) -> [FuseResult<Item>] {
        if case .pattern(let pattern) = query {
            return fuse.search(pattern, limit: limit)
        }
        return fuse.search(query.fuseQuery, limit: limit)
    }

    @Test("async search agrees with sync search", arguments: caseNames.filter { $0.hasPrefix("books") || $0.hasPrefix("strings default") })
    func asyncParity(caseName: String) async throws {
        let testCase = Self.fixture.cases.first { $0.name == caseName }!
        let options = testCase.options.fuseOptions
        guard let keyDefinitions = testCase.keys, case .pattern(let pattern) = testCase.query else {
            let fuse = Fuse(testCase.collection.map { $0.text! }, options: options)
            guard case .pattern(let pattern) = testCase.query else { return }
            let sync = snapshots(syncSearch(fuse, pattern, limit: testCase.limit))
            let async = snapshots(try await fuse.search(pattern, limit: testCase.limit))
            #expect(sync == async)
            return
        }
        let keys = keyDefinitions.map { definition in
            FuseKey<Doc>(definition.name, weight: definition.weight ?? 1) { $0.key(named: definition.name) }
        }
        let fuse = Fuse(testCase.collection, keys: keys, options: options)
        let sync = snapshots(syncSearch(fuse, pattern, limit: testCase.limit))
        let async = snapshots(try await fuse.search(pattern, limit: testCase.limit))
        #expect(sync == async)
    }
}
